def make_request(endpoint: str) -> APIResponse:
    """Simulate API request"""
    if endpoint == "/users":
        return {
            "status": 200,
            "message": "Success",
            "data": {"users": ["Alice", "Bob"]},
        }
    else:
        return {"status": 404, "message": "Not Found", "data": None}

def handle_response(response: APIResponse) -> None:
    print(f"  Status: {response['status']}")
    print(f"  Message: {response['message']}")
    if response["data"]:
        print(f"  Data: {response['data']}")

print("API Responses:")
handle_response(make_request("/users"))
handle_response(make_request("/invalid"))

